#include<bits/stdc++.h>
#define int long long
using namespace std;
int n,a[222],ans[222][222],a5[222],a2[222];

int dfs(int p,int k,int p2,int p5){
	if(p>n){
		if(k==0){
			return min(p2,p5);
		}else{
			return 0;
		}
	}
	if(ans[p][k]!=-1){
		return ans[p][k];
	}
	int x=dfs(p+1,k,p2,p5);
	if(k>0){
		x=max(x,dfs(p+1,k-1,p2+a2[p],p5+a5[p]));
	}
	ans[p][k]=x;
	return x;
}
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int k;
	cin>>n>>k;
	memset(ans,-1,sizeof(ans));
	for(int i=1;i<=n;i++){
		cin>>a[i];
		while(a[i]%2==0){
			a[i]/=2;
			a2[i]++;
		}
		while(a[i]%5==0){
			a[i]/=5;
			a5[i]++;
		}
	}
	cout<<dfs(1,k,0,0);
    return 0;
}
